<?php
use VazinCMS\Security;

$labels = ['new'=>'جدید','awaiting_payment'=>'منتظر پرداخت','paid'=>'پرداخت‌شده','reviewing'=>'در حال بررسی','documents_required'=>'نیازمند مدرک','processing'=>'در حال انجام','completed'=>'تکمیل‌شده','rejected'=>'ردشده','cancelled'=>'لغوشده'];
$docLabels = ['passport'=>'گذرنامه','photo'=>'عکس','insurance'=>'بیمه','invitation'=>'دعوت‌نامه','education'=>'تحصیلی','financial'=>'مالی','booking'=>'رزرو','other'=>'سایر'];
$manualCase = ($order['payment_status'] ?? '') === 'not_required' || (float) ($order['amount'] ?? 0) === 0.0;
$application = is_array($application ?? null) ? $application : ['state' => 'missing'];
$intake = is_array($application['payload'] ?? null) ? $application['payload'] : [];
$metadata = is_array($application['metadata'] ?? null) ? $application['metadata'] : [];
$field = static function (array $section, string $key): string {
    $value = $section[$key] ?? null;
    if (is_bool($value)) return $value ? 'بله' : 'خیر';
    return trim((string) $value) !== '' ? (string) $value : '—';
};
