<section class="split"><div class="panel"><h2>وضعیت و پیام مشتری</h2><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><input type="hidden" name="action" value="status"><label>وضعیت<select name="status"><?php foreach($labels as$v=>$l):?><option value="<?=$v?>" <?=$order['status']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label>پیام همراه تغییر<textarea name="message" rows="4" placeholder="توضیحی که مشتری در خط زمانی می‌بیند"></textarea></label><button>ذخیره وضعیت</button></form><hr><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><input type="hidden" name="action" value="message"><label>یادداشت یا پیام<textarea name="message" rows="4" required></textarea></label><label>نمایش<select name="visibility"><option value="customer">قابل مشاهده برای مشتری</option><option value="internal">فقط مدیران</option></select></label><button class="secondary">ثبت پیام</button></form></div><div class="panel"><h2>اطلاعات پرونده</h2><dl><dt>ملیت</dt><dd><?=Security::e((string)$order['nationality'])?></dd><dt>تعداد متقاضی</dt><dd><?=(int)$order['travelers']?></dd><dt>تاریخ سفر</dt><dd><span dir="ltr"><?=Security::e((string)($order['travel_date']?:'—'))?></span></dd><dt>توضیحات اولیه</dt><dd><?=nl2br(Security::e((string)($order['notes']?:'—')))?></dd><?php if(!$manualCase):?><dt>مرجع پرداخت</dt><dd><code><?=Security::e((string)($order['payment_reference']?:'—'))?></code></dd><?php endif;?></dl></div></section>
