فر</h3><dl><dt>اقامت</dt><dd><?=Security::e($field((array)($intake['residence_contact']??[]),'country'))?> · <?=Security::e($field((array)($intake['residence_contact']??[]),'city'))?></dd><dt>نشانی اقامت</dt><dd><?=Security::e($field((array)($intake['residence_contact']??[]),'address'))?></dd><dt>ایمیل</dt><dd dir="ltr"><?=Security::e($field((array)($intake['residence_contact']??[]),'email'))?></dd><dt>تلفن</dt><dd dir="ltr"><?=Security::e($field((array)($intake['residence_contact']??[]),'phone'))?></dd><dt>مقصد و نوع ویزا</dt><dd><?=Security::e($field((array)($intake['itinerary']??[]),'destination'))?> · <?=Security::e($field((array)($intake['itinerary']??[]),'visa_type'))?></dd><dt>ورود و سفر</dt><dd><?=Security::e($field((array)($intake['itinerary']??[]),'entry_count'))?> · <span dir="ltr"><?=Security::e($field((array)($intake['itinerary']??[]),'arrival_date'))?> تا <?=Security::e($field((array)($intake['itinerary']??[]),'departure_date'))?></span></dd><dt>محل اقامت</dt><dd><?=Security::e($field((array)($intake['itinerary']??[]),'accommodation_name'))?><br><?=Security::e($field((array)($intake['itinerary']??[]),'accommodation_address'))?></dd></dl></div></div><div class="split"><div><h3>کار و سابقهٔ سفر</h3><dl><dt>وضعیت شغلی</dt><dd><?=Security::e($field((array)($intake['work_travel']??[]),'employment_status'))?></dd><dt>محل کار / تحصیل</dt><dd><?=Security::e($field((array)($intake['work_travel']??[]),'employer_name'))?><br><?=Security::e($field((array)($intake['work_travel']??[]),'employer_address'))?></dd><dt>هدف سفر</dt><dd><?=nl2br(Security::e($field((array)($intake['work_travel']??[]),'travel_purpose')))?></dd><dt>سابقهٔ ویزا</dt><dd><?=Security::e($field((array)($intake['work_travel']??[]),'previous_visa'))?><br><?=nl2br(Security::e($field((array)($intake['work_travel']??[]),'previous_visa_details')))?></dd><dt>توضیحات تکمیلی</dt><dd><?=nl2br(Security::e($field((array)($intake['work_travel']??[]),'additional_information')))?></dd></dl></div><div><h3>تماس اضطراری و رضایت</h3><dl><dt>نام و نسبت</dt><dd><?=Security::e($field((array)($intake['emergency_contact']??[]),'name'))?> · <?=Security::e($field((array)($intake['emergency_contact']??[]),'relation'))?></dd><dt>تلفن</dt><dd dir="ltr"><?=Security::e($field((array)($intake['emergency_contact']??[]),'phone'))?></dd><dt>صحت اطلاعات</dt><dd><?=Security::e($field((array)($intake['consent']??[]),'accuracy'))?></dd><dt>رضایت حریم خصوصی</dt><dd><?=Security::e($field((array)($intake['consent']??[]),'privacy'))?></dd><dt>نسخه / زمان رضایت</dt><dd><span dir="ltr"><?=Security::e($field((array)($intake['consent']??[]),'version'))?> · <?=Security::e($field((array)($intake['consent']??[]),'captured_at'))?></span></dd><dt>ثبت / نگهداری تا</dt><dd><span dir="ltr"><?=Security::e((string)($metadata['completed_at']??'—'))?> · <?=Security::e((string)($metadata['retention_until']??'—'))?></span></dd></dl></div></div><?php endif;?></section>
